import {useState} from 'react';
import {Pressable,StyleSheet,Text,View} from '@/platform/react-native';
import {router,useLocalSearchParams} from '@/router';
import {useQuery} from '@tanstack/react-query';
import {Ionicons} from '@/platform/icons';
import {api} from '@/lib/api';
import {Badge,Card,EmptyState,Muted,Screen,TabBar,useAppTheme} from '@/components/UI';

type Period='current'|'past';
export default function FinancialRecord(){
 const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const[period,setPeriod]=useState<Period>('current');
 const caps=useQuery<any>({queryKey:['capabilities',id],queryFn:async()=>(await api.get(`/communities/${id}/capabilities`)).data});
 const allowed=caps.data?.permissions?.includes('FINANCE_MANAGE');
 const levies=useQuery<any[]>({queryKey:['finance-levies',id,period],enabled:allowed,queryFn:async()=>(await api.get(`/communities/${id}/finance/levies`,{params:{period}})).data});
 return <Screen scroll contentStyle={s.page}>{caps.isLoading?<Muted>Checking finance permission…</Muted>:!allowed?<EmptyState icon="lock-closed-outline" title="Admin or moderator access required" body="Financial Record is available only to authorised community administrators and moderators."/>:<><TabBar value={period} onChange={setPeriod} items={[{key:'current',label:'Current Levy',icon:'receipt-outline'},{key:'past',label:'Past Levy',icon:'time-outline'}]}/>{levies.isLoading?<Muted>Loading levies…</Muted>:!levies.data?.length?<EmptyState icon="receipt-outline" title={`No ${period} levies`} body="Use Create Levy in the header to assign a levy to all or selected community members."/>:levies.data.map(x=><Pressable key={x.Id} onPress={()=>router.push(`/community/${id}/levy/${x.Id}` as any)}><Card><View style={s.row}><View style={[s.icon,{backgroundColor:palette.successSoft}]}><Ionicons name="business-outline" size={25} color={palette.success}/></View><View style={{flex:1}}><View style={s.row}><Text style={[s.title,{color:palette.text,flex:1}]}>{x.Name}</Text><Badge text={x.IsActive?'Active':'Closed'} tone={x.IsActive?'green':'gray'}/></View><Muted>{x.Description}</Muted><Text style={[s.money,{color:palette.success}]}>{x.CurrencyCode} {Number(x.Amount).toLocaleString(undefined,{minimumFractionDigits:2})}</Text><View style={s.stats}><Muted>{x.Frequency?.replace('_',' ')}</Muted><Muted>{x.PaidCount}/{x.AssignedCount} paid</Muted>{Number(x.PendingCount)>0?<Badge text={`${x.PendingCount} awaiting approval`} tone="orange"/>:null}</View></View><Ionicons name="chevron-forward" size={22} color={palette.muted}/></View></Card></Pressable>)}</>}</Screen>;
}
const s=StyleSheet.create({page:{maxWidth:900,alignSelf:'center',paddingBottom:120},row:{flexDirection:'row',alignItems:'center',gap:12},icon:{width:52,height:52,borderRadius:26,alignItems:'center',justifyContent:'center'},title:{fontSize:17,fontWeight:'900'},money:{fontSize:20,fontWeight:'900',marginTop:10},stats:{flexDirection:'row',alignItems:'center',gap:10,flexWrap:'wrap',marginTop:7}});
